alter table public.screening_reports add column if not exists cv_evidence_used boolean not null default false;alter table public.screening_reports add column if not exists reviewed_at timestamptz;alter table public.screening_reports add column if not exists reviewed_by uuid references auth.users(id);create or replace function public.signoff_screening_report(p_report_id uuid) returns void language plpgsql security definer set search_path='' as $$declare p public.profiles%rowtype;begin select * into p from public.profiles where id=auth.uid() and role in ('owner','manager','recruiter');if not found then raise exception 'Staff access required';end if;update public.screening_reports set reviewed_at=now(),reviewed_by=auth.uid() where id=p_report_id and company_id=p.company_id;if not found then raise exception 'Report not found';end if;end$$;revoke all on function public.signoff_screening_report(uuid) from public,anon;grant execute on function public.signoff_screening_report(uuid) to authenticated;
